constexpr int N_SEM=56,N_DELTA_SEM=55,N_H=4,N_ACT=24,N_EVENTS=44,R1_WIDTH=N_DELTA_SEM*N_H+N_H+N_H+N_ACT*N_H+N_EVENTS;
__device__ __forceinline__ int horizon(int i){return i==0?1:(i==1?4:(i==2?24:72));}
#pragma pack(push,1)
struct Header{char magic[8];uint32_t version,cases,probes,width;};
#pragma pack(pop)
struct Semantic{int32_t v[N_SEM];};
struct ActionPrefix{int32_t v[N_ACT];};
struct EventState{int32_t v[N_EVENTS];};
struct CaseHost{std::string path;int seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct CaseDev{int tape=0,seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct OppDesc{int first=0,count=0;};
struct DevicePolicyOwner4{bonsaikg4::Node4*n=nullptr;uint16_t*c=nullptr;bonsaikg4::BbDecl4*bb=nullptr;bonsaikg4::ValueRef4*v=nullptr;bonsaikg4::FeatureArgRef4*a=nullptr;bonsaikg4::Predicate4*q=nullptr;bonsaikg4::Lifecycle4*l=nullptr;bonsaikg4::Effect4*e=nullptr;~DevicePolicyOwner4(){if(n)cudaFree(n);if(c)cudaFree(c);if(bb)cudaFree(bb);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}};
template<class T>static T*cp(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,v.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}
static std::vector<std::string>split_tab(const std::string&s){std::vector<std::string>o;size_t p=0;for(;;){size_t q=s.find('\t',p);o.push_back(s.substr(p,q==std::string::npos?std::string::npos:q-p));if(q==std::string::npos)break;p=q+1;}return o;}
static std::vector<CaseHost>load_cases(const std::string&p){std::ifstream in(p);if(!in)throw std::runtime_error("cases");std::vector<CaseHost>o;std::string l;while(std::getline(in,l)){if(l.empty()||l[0]=='#')continue;auto z=split_tab(l);if(z.size()!=7)throw std::runtime_error("case fields");CaseHost c;c.path=z[0];c.seat=std::stoi(z[1]);c.seed=std::stoull(z[2]);c.family=std::stoi(z[3]);c.protected_flag=std::stoi(z[4]);c.own_history=std::stoi(z[5]);c.role=std::stoi(z[6]);o.push_back(c);}if(o.empty())throw std::runtime_error("empty cases");return o;}
static std::vector<int>load_probes(const std::string&p){std::ifstream in(p);if(!in)throw std::runtime_error("probes");std::vector<int>o;int x;while(in>>x)o.push_back(x);if(o.empty())throw std::runtime_error("empty probes");return o;}
static bonsaikg_v6::RoutePack load_legacy_pack(const std::string&path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("legacy");std::vector<uint8_t>raw((std::istreambuf_iterator<char>(in)),{});auto full=bonsaikg::sha256_bytes(raw);if(bonsaikg_v6::hash_hex(full)!=bonsaikg4_champion::LEGACY_ROUTE_PACK_SHA256)throw std::runtime_error("legacy hash");bonsaikg_v6::PackHeader h{};std::memcpy(&h,raw.data(),sizeof(h));size_t db=(size_t)h.route_count*sizeof(bonsaikg_v6::RouteDesc);bonsaikg_v6::RoutePack o;o.routes.resize(h.route_count);o.actions.resize(h.action_count);std::memcpy(o.routes.data(),raw.data()+sizeof(h),db);std::memcpy(o.actions.data(),raw.data()+sizeof(h)+db,o.actions.size()*sizeof(o.actions[0]));return o;}
struct DeviceBasePack{const bonsaikg_v6::RouteDesc*routes=nullptr;const bonsaikg_v6::PackedAction*actions=nullptr;int n=0;__device__ __forceinline__ const bonsaikg_v6::PackedAction*at(uint16_t route,int step)const{for(int i=0;i<n;++i)if(routes[i].route_id==route){int s=step;if(s<0)s=0;if(s>=routes[i].steps)s=routes[i].steps-1;return actions+routes[i].first+s;}return nullptr;}};
__device__ __forceinline__ void reconcile_feed(const int32_t*bb,int first,int count,Action&a){for(int u=0;u<count&&u<a.n_units;++u)if(bb[first+u]&&a.units[u].op==OP_FEED)a.units[u]=UnitAction{};}
__device__ __forceinline__ bool build_final_action(const ObservationView&raw,const DeviceBasePack&bp,const bonsaikg4_champion::CudaLegacyPack&lp,bonsaikg4_champion::CudaLegacyState&legacy,bonsaikg_v6::CudaEngineExploitState&exploit,const int32_t*bb,int feed_slot,int feed_count,Action&out){const auto*p=bp.at((uint16_t)bb[1],raw.step());if(!p)return false;bonsaikg_v6::materialize_cuda(*p,raw.farm(raw.player()).n_units(),out);bonsaikg4_champion::apply_legacy(raw,lp,legacy,out);bonsaikg_v6::apply_cuda_engine_exploits(raw,out,exploit,legacy.external_ok!=0,100);reconcile_feed(bb,feed_slot,feed_count,out);return true;}
__device__ __forceinline__ int crop_count(const PublicFarmView&f,int crop){int n=0;for(int y=0;y<BOARD;++y)for(int x=0;x<BOARD;++x){const Tile&t=f.tile(x,y);n+=t.kind==T_PLANT&&t.what==crop;}return n;}
__device__ __forceinline__ int animal_count(const PublicFarmView&f,int animal){int n=0;for(int y=0;y<BOARD;++y)for(int x=0;x<BOARD;++x){const Tile&t=f.tile(x,y);n+=t.has_animal&&t.what==animal;}return n;}
__device__ __forceinline__ int kind_count(const PublicFarmView&f,int kind){int n=0;for(int y=0;y<BOARD;++y)for(int x=0;x<BOARD;++x)n+=f.tile(x,y).kind==kind;return n;}
__device__ __forceinline__ Semantic semantic(const ObservationView&o,int route){Semantic s{};int k=0;for(int i=0;i<N_PRODUCTS;++i)s.v[k++]=o.market().inventory(i);for(int i=0;i<N_PRODUCTS;++i)s.v[k++]=o.market().price(i);const int me=o.player();auto own=o.farm(me),opp=o.farm(1-me);s.v[k++]=(int32_t)own.money();s.v[k++]=(int32_t)opp.money();s.v[k++]=own.n_units();s.v[k++]=opp.n_units();s.v[k++]=own.n_quadrants();s.v[k++]=opp.n_quadrants();s.v[k++]=own.hires_today();s.v[k++]=opp.hires_today();for(int i=0;i<N_CROPS;++i)s.v[k++]=crop_count(opp,i);for(int i=0;i<N_ANIMALS;++i)s.v[k++]=animal_count(opp,GOOSE+i);for(int kind=0;kind<=5;++kind)s.v[k++]=kind_count(opp,kind);for(int i=0;i<N_CROPS;++i)s.v[k++]=crop_count(own,i);for(int i=0;i<N_ANIMALS;++i)s.v[k++]=animal_count(own,GOOSE+i);for(int kind=0;kind<=5;++kind)s.v[k++]=kind_count(own,kind);s.v[k++]=o.town().n_shops();s.v[k++]=route;return s;}
__device__ __forceinline__ void init_events(EventState&e){for(int i=0;i<N_EVENTS;++i)e.v[i]=9999;}
__device__ __forceinline__ void bump(EventState&e){for(int i=0;i<N_EVENTS;++i)if(e.v[i]<9999)++e.v[i];}
__device__ __forceinline__ bool any_diff(const Semantic&a,const Semantic&b,int first,int count){for(int i=0;i<count;++i)if(a.v[first+i]!=b.v[first+i])return true;return false;}
__device__ __forceinline__ void update_events(EventState&e,const Semantic&prev,const Semantic&cur){bump(e);if(cur.v[23]>prev.v[23])e.v[0]=0;if(cur.v[21]>prev.v[21])e.v[1]=0;if(any_diff(prev,cur,26,5))e.v[2]=0;if(any_diff(prev,cur,31,3))e.v[3]=0;if(cur.v[37]!=prev.v[37]||cur.v[38]!=prev.v[38])e.v[4]=0;if(cur.v[36]!=prev.v[36])e.v[5]=0;if(cur.v[54]>prev.v[54])e.v[6]=0;if(cur.v[55]!=prev.v[55])e.v[7]=0;for(int item=0;item<N_PRODUCTS;++item){int p=prev.v[item],c=cur.v[item],b=8+item*4;if(c>p)e.v[b]=0;if(c<p)e.v[b+1]=0;if(p>=10000&&c<10000)e.v[b+2]=0;if(p<=10000&&c>10000)e.v[b+3]=0;}}
__device__ __forceinline__ void add_action(ActionPrefix&cum,const Action&a){for(int u=0;u<a.n_units;++u)if(a.units[u].op<=OP_CARE)++cum.v[a.units[u].op];for(int i=0;i<a.n_orders;++i)if(a.orders[i].op>=M_HIRE&&a.orders[i].op<=M_SELL)++cum.v[18+(a.orders[i].op-M_HIRE)];}
__device__ __forceinline__ void capture_r1(int step,const Semantic&cur,const Semantic*semring,const ActionPrefix&cum,const ActionPrefix*aring,const EventState&e,int32_t*out){int k=0;for(int hi=0;hi<N_H;++hi){int h=horizon(hi),valid=step>=h;const Semantic&old=semring[(step-h+73)%73];for(int j=0;j<N_DELTA_SEM;++j)out[k++]=valid?cur.v[j]-old.v[j]:0;}for(int hi=0;hi<N_H;++hi){int h=horizon(hi);out[k++]=step>=h?semring[(step-h+73)%73].v[55]:-1;}for(int hi=0;hi<N_H;++hi)out[k++]=step>=horizon(hi);for(int hi=0;hi<N_H;++hi){int h=horizon(hi),valid=step>=h;const ActionPrefix&old=aring[(step-h+73)%73];for(int j=0;j<N_ACT;++j)out[k++]=valid?cum.v[j]-old.v[j]:0;}for(int j=0;j<N_EVENTS;++j)out[k++]=e.v[j];}
__global__ void kernel(Config cfg0,DeviceTables tables,bonsaikg4::PolicyView4 policy,DeviceBasePack bp,bonsaikg4_champion::CudaLegacyPack lp,const Action*opp,const OppDesc*od,const CaseDev*cases,int nc,const int*probes,int np,int feed_slot,int feed_count,int32_t*bb,bonsaikg4::NodeState4*ns,bonsaikg4::RuntimeMeta4*meta,Sim*sims,Semantic*semring,ActionPrefix*aring,int32_t*frames,uint16_t*flags){int ci=blockIdx.x*blockDim.x+threadIdx.x;if(ci>=nc)return;const CaseDev c=cases[ci];Config cfg=cfg0;cfg.seed=c.seed;Sim&sim=sims[ci];sim.init(cfg,&tables);bonsaikg4::RuntimeView4 st{policy.n_bb?bb+(size_t)ci*policy.n_bb:nullptr,policy.n_state?ns+(size_t)ci*policy.n_state:nullptr,meta+ci};bonsaikg4::reset_runtime(policy,st);bonsaikg4_champion::CudaLegacyState legacy{};bonsaikg_v6::CudaEngineExploitState exploit{};EventState ev{};init_events(ev);ActionPrefix cum{};Semantic prev{};bool have_prev=false;int pi=0;uint16_t fl=0;Semantic*sr=semring+(size_t)ci*73;ActionPrefix*ar=aring+(size_t)ci*73;while(!sim.st.done){int step=sim.st.step,os=1-c.seat;ObservationView raw=make_observation(sim,c.seat);bonsaikg4::CudaObservation4 obs4(raw);bonsaikg4::ActionResult4 ignored{};auto status=bonsaikg4::tick4(policy,st,obs4,0,ignored,nullptr);if(meta[ci].fault||status!=bonsaikg4::SUCCESS){fl|=1;break;}Action ca{};if(!build_final_action(raw,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,ca)){fl|=2;break;}Semantic cur=semantic(raw,st.blackboard[1]);if(have_prev)update_events(ev,prev,cur);ar[step%73]=cum;if(pi<np&&step==probes[pi]){capture_r1(step,cur,sr,cum,ar,ev,frames+((size_t)ci*np+pi)*R1_WIDTH);++pi;}sr[step%73]=cur;prev=cur;have_prev=true;add_action(cum,ca);Action oa{};OppDesc d=od[c.tape];if(d.count){int s=step<d.count?step:d.count-1;oa=opp[d.first+s];}oa.n_units=sim.st.farms[os].n_units;if(c.seat==0)sim.step_with_unit_counts(ca,sim.st.farms[0].n_units,oa,sim.st.farms[1].n_units);else sim.step_with_unit_counts(oa,sim.st.farms[0].n_units,ca,sim.st.farms[1].n_units);}if(pi!=np)fl|=4;flags[ci]=fl;}
static void write_out(const std::string&p,const std::vector<int>&probes,const std::vector<int32_t>&f,int nc){std::ofstream o(p,std::ios::binary);Header h{{'B','4','I','S','R','1','1','\0'},1u,(uint32_t)nc,(uint32_t)probes.size(),(uint32_t)R1_WIDTH};o.write((char*)&h,sizeof(h));for(int x:probes){int32_t y=x;o.write((char*)&y,4);}o.write((char*)f.data(),f.size()*4);}
}
int main(int argc,char**argv){try{std::string controller,routes,legacy,casesp,probesp,outp;int feed_slot=5,feed_count=13,tpb=64;for(int i=1;i<argc;++i){std::string a=argv[i];auto need=[&](){if(i+1>=argc)throw std::runtime_error("missing "+a);return std::string(argv[++i]);};if(a=="--controller")controller=need();else if(a=="--routes")routes=need();else if(a=="--legacy-routes")legacy=need();else if(a=="--cases")casesp=need();else if(a=="--probes")probesp=need();else if(a=="--out")outp=need();else if(a=="--feed-slot")feed_slot=std::stoi(need());else if(a=="--feed-count")feed_count=std::stoi(need());else if(a=="--tpb")tpb=std::stoi(need());else throw std::runtime_error("unknown "+a);}if(controller.empty()||routes.empty()||legacy.empty()||casesp.empty()||probesp.empty()||outp.empty())throw std::runtime_error("required args");auto owned=bonsaikg4::load_compiled4(controller);auto hp=owned.view();DevicePolicyOwner4 po;po.n=cp(owned.nodes);po.c=cp(owned.child_refs);po.bb=cp(owned.bb);po.v=cp(owned.values);po.a=cp(owned.feature_args);po.q=cp(owned.predicates);po.l=cp(owned.lifecycles);po.e=cp(owned.effects);auto dp=hp;dp.nodes=po.n;dp.child_refs=po.c;dp.bb=po.bb;dp.values=po.v;dp.feature_args=po.a;dp.predicates=po.q;dp.lifecycles=po.l;dp.effects=po.e;auto rp=bonsaikg_v6::RoutePack::load(routes),lg=load_legacy_pack(legacy);auto*dr=cp(rp.routes);auto*da=cp(rp.actions);auto*dlr=cp(lg.routes);auto*dla=cp(lg.actions);DeviceBasePack bp{dr,da,(int)rp.routes.size()};bonsaikg4_champion::CudaLegacyPack lp{dlr,dla,(int)lg.routes.size()};auto hc=load_cases(casesp);auto probes=load_probes(probesp);std::vector<Action>hoa;std::vector<OppDesc>hod;std::vector<CaseDev>hcd;for(const auto&c:hc){auto t=load_native_tape_json(c.path);int off=(int)hoa.size();hoa.insert(hoa.end(),t.actions.begin(),t.actions.end());hod.push_back({off,(int)t.actions.size()});hcd.push_back({(int)hod.size()-1,c.seat,c.seed,c.family,c.protected_flag,c.own_history,c.role});}auto*doa=cp(hoa);auto*dod=cp(hod);auto*dc=cp(hcd);auto*dpr=cp(probes);int nc=hc.size(),np=probes.size();int32_t*dbb=nullptr;bonsaikg4::NodeState4*dns=nullptr;bonsaikg4::RuntimeMeta4*dm=nullptr;Sim*ds=nullptr;Semantic*dsr=nullptr;ActionPrefix*dar=nullptr;int32_t*df=nullptr;uint16_t*dflags=nullptr;if(hp.n_bb)KAGCUDA_CHECK(cudaMalloc((void**)&dbb,(size_t)nc*hp.n_bb*4));if(hp.n_state)KAGCUDA_CHECK(cudaMalloc((void**)&dns,(size_t)nc*hp.n_state*sizeof(*dns)));KAGCUDA_CHECK(cudaMalloc((void**)&dm,(size_t)nc*sizeof(*dm)));KAGCUDA_CHECK(cudaMalloc((void**)&ds,(size_t)nc*sizeof(*ds)));KAGCUDA_CHECK(cudaMalloc((void**)&dsr,(size_t)nc*73*sizeof(*dsr)));KAGCUDA_CHECK(cudaMalloc((void**)&dar,(size_t)nc*73*sizeof(*dar)));KAGCUDA_CHECK(cudaMemset(dsr,0,(size_t)nc*73*sizeof(*dsr)));KAGCUDA_CHECK(cudaMemset(dar,0,(size_t)nc*73*sizeof(*dar)));KAGCUDA_CHECK(cudaMalloc((void**)&df,(size_t)nc*np*R1_WIDTH*4));KAGCUDA_CHECK(cudaMalloc((void**)&dflags,(size_t)nc*2));configure_device();TablesOwner tables;Config cfg;cfg.episode_steps=720;cudaEvent_t e0,e1;KAGCUDA_CHECK(cudaEventCreate(&e0));KAGCUDA_CHECK(cudaEventCreate(&e1));KAGCUDA_CHECK(cudaEventRecord(e0));kernel<<<(nc+tpb-1)/tpb,tpb>>>(cfg,tables.dev,dp,bp,lp,doa,dod,dc,nc,dpr,np,feed_slot,feed_count,dbb,dns,dm,ds,dsr,dar,df,dflags);KAGCUDA_CHECK(cudaGetLastError());KAGCUDA_CHECK(cudaEventRecord(e1));KAGCUDA_CHECK(cudaEventSynchronize(e1));float ms=0;KAGCUDA_CHECK(cudaEventElapsedTime(&ms,e0,e1));std::vector<int32_t>hf((size_t)nc*np*R1_WIDTH);std::vector<uint16_t>flags(nc);KAGCUDA_CHECK(cudaMemcpy(hf.data(),df,hf.size()*4,cudaMemcpyDeviceToHost));KAGCUDA_CHECK(cudaMemcpy(flags.data(),dflags,nc*2,cudaMemcpyDeviceToHost));int bad=0;for(auto x:flags)bad+=x!=0;write_out(outp,probes,hf,nc);std::cout<<"r1 cases="<<nc<<" probes="<<np<<" width="<<R1_WIDTH<<" gpu_ms="<<ms<<" bad="<<bad<<" output_MiB="<<(hf.size()*4/(1024.0*1024.0))<<"\n";cudaFree(dr);cudaFree(da);cudaFree(dlr);cudaFree(dla);cudaFree(doa);cudaFree(dod);cudaFree(dc);cudaFree(dpr);if(dbb)cudaFree(dbb);if(dns)cudaFree(dns);cudaFree(dm);cudaFree(ds);cudaFree(dsr);cudaFree(dar);cudaFree(df);cudaFree(dflags);cudaEventDestroy(e0);cudaEventDestroy(e1);return bad?1:0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
